/**
 * Drops fenced and inline code before mention scanning.
 *
 * Fences follow the comment renderer: a line whose trimmed text starts with
 * ``` toggles a block, and an unclosed fence runs to the end of the body.
 * Closing on any ``` in the text would end the block early inside shell
 * snippets (`echo '```'`, heredocs), so words like `@types` or `@alice`
 * would still notify. Inline spans are single-line, same as `renderInline`.
 */
function withoutCode(body: string): string {
  const lines = body.replace(/\r\n/g, "\n").split("\n");
  const kept: string[] = [];
  let inFence = false;

  for (const line of lines) {
    if (line.trimStart().startsWith("```")) {
      inFence = !inFence;
      kept.push("");
      continue;
    }
    kept.push(inFence ? "" : line.replace(/`[^`]*`/g, " "));
  }

  return kept.join("\n");
}

